  "with_retry|with_fallbacks": { tip: "LangChain methods that wrap a model so it retries failed calls, or switches to a backup model.", only: ["riq", "story"] },
  "Runnable": { tip: "LangChain's common interface: models, prompts and chains all offer invoke, stream and batch.", only: ["riq", "story"] },
  "Vertex AI": "Google Cloud's managed platform for using Gemini and other models with enterprise controls.",
  "text layer": "The real, selectable characters stored in a PDF page. Scanned pages have none, only an image, so they need OCR.",
  "lattice mode|stream mode": "Camelot's two table modes: lattice finds cells from ruled lines; stream infers columns from white space in borderless tables.",
  "pypdf|PyPDF2|PyPDF": "Pure-Python PDF library for splitting, merging and simple text extraction; gives little layout detail. PyPDF2 was merged back into pypdf.",
  /* Scoped: "unstructured" is also an ordinary word ("unstructured data") on other pages. */
  "Unstructured": { tip: "Open-source toolkit that splits many file types into typed elements such as Title, NarrativeText and Table.", only: ["riq", "story"] },
  "pdfminer.six|pdfminer": "Python library that reads every character and its position from a PDF; pdfplumber is built on it.",
  "AGPL": "A strong open-source licence: if you offer the software over a network, you must share your source code, or buy a commercial licence.",
  "pandas": "The standard Python library for tables of data (DataFrames): reading Excel and CSV, filtering, grouping and sums.",
  "xlrd": "Python library for reading old .xls Excel files; pandas uses it for that format.",
  "magic bytes|file signature": "The fixed first bytes that identify a file's real format, such as %PDF for PDF or PK for zip-based Office files.",
  "MIME type": "A label for a file's format, such as application/pdf, sent with uploads. It comes from the sender, so it can be wrong.",
