  "ruling lines": { tip: "The drawn horizontal and vertical lines of a bordered table; libraries use their crossings to find cells.", only: ["riq", "story"] },
  "rowspan|colspan": "HTML table attributes that let one cell cover several rows or columns, which Markdown tables can't show.",
