  "page furniture": { tip: "Repeated page elements that aren't content: headers, footers, page numbers, logos.", only: ["riq", "story"] },
  "BGE": "BAAI General Embedding: a family of open-source embedding and reranker models (BGE-large, bge-reranker) that rank well on public benchmarks.",
  "MTEB": "Massive Text Embedding Benchmark: a public leaderboard that scores embedding models on many search, clustering and classification tasks.",
  "ada-002": "OpenAI's older text-embedding-ada-002 model (1,536 dimensions), replaced by text-embedding-3-small and -large.",
  "all-mpnet-base-v2": "A popular open-source sentence-embedding model (768 dimensions) from the Sentence Transformers library.",
  "RecursiveCharacterTextSplitter": "LangChain's general-purpose text splitter: it splits on paragraph breaks, then line breaks, then spaces, only as far as needed to fit the size.",
  "NLTK": "Natural Language Toolkit: a Python library with classic text tools such as sentence splitting and stemming.",
  "parent_id": { tip: "A metadata field on each small chunk pointing to its larger parent section, used for parent-child retrieval.", only: ["riq", "story"] },
  "dot_product": { tip: "The Elasticsearch name for dot-product similarity, which ranks the same as cosine when vectors are normalised.", only: ["riq", "story"] },
  "SharePoint": "Microsoft's document storage and intranet platform, a common source of company documents.",
  "Lucene": "The open-source Java search library underneath Elasticsearch and OpenSearch. It holds the inverted index and HNSW vector graphs.",
  "segment|segments|Lucene segment": { tip: "An immutable piece of a Lucene shard. New data creates new segments; merging combines them. Each has its own HNSW graph.", only: ["riq", "story"] },
  "JVM|heap": { tip: "Java Virtual Machine, which runs Elasticsearch. The heap is its managed memory; too small or too large slows the cluster.", only: ["riq", "story"] },
  "num_candidates": "Elasticsearch kNN setting: how many candidates HNSW collects per shard before returning the top k. Higher means better recall, slower search.",
  "ef_search": "The HNSW query-time setting for how many candidates to keep while searching. Elasticsearch calls it num_candidates.",
