  "post-filtering|post-filter": "Filtering results after the vector search. Simple, but can leave few or no results if most matches are filtered out.",
  "bulk API": "Elasticsearch endpoint that writes or deletes many documents in one request, much faster than one at a time.",
  "keyword field": "An Elasticsearch field type stored as one exact value, not split into words. Used for filters, IDs and tags.",
  "mapping": { tip: "An Elasticsearch index's schema: each field's type (text, keyword, dense_vector, date) and settings.", only: ["riq", "story"] },
  "int8": "An 8-bit whole number. Storing vector values as int8 instead of 32-bit floats cuts memory by four.",
  "top_k|top-k retrieval": "How many results a search returns. In RAG, often set twice: candidates for the reranker and chunks for the prompt.",
