  "dead-letter queue|dead-letter": { tip: "A holding queue for jobs that failed all their retries, so they can be inspected and rerun instead of lost.", only: ["riq", "story"] },
  "Prometheus": "Open-source monitoring system that collects numeric metrics, such as latency and error counts, and triggers alerts.",
  "Grafana": "Open-source dashboard tool that charts metrics from sources such as Prometheus.",
  "Cohere Rerank": "A hosted reranking API from Cohere. Good quality, but document text is sent to the vendor.",
